theming.sample:
class ContosoAliasTokens : AliasTokens() {
    override val brandColor: TokenSet<FluentAliasTokens.BrandColorTokens, Color> by lazy {
        TokenSet { token ->
            when (token) {
                FluentAliasTokens.BrandColorTokens.Color80 -> Color(0xFF7719AA)
                else -> super.brandColor[token]
            }
        }
    }
}

FluentTheme(aliasTokens = ContosoAliasTokens(), themeMode = ThemeMode.Auto) { App() }
